extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var inv_script: GDScript = load("res://inventory.gd") as GDScript
	if not check("inv_script", inv_script != null, "Lo script res://inventory.gd deve esistere e compilare senza errori"):
		return
	var inv = inv_script.new(2)
	check("inv_init", get_prop(inv, "max_slots") == 2, "max_slots deve essere impostato a 2 tramite il costruttore")

	var add_potion = call_if_exists(inv, "add_item", ["potion", 3], false)
	check("add_potion", add_potion == true, "add_item('potion', 3) deve restituire true")
	check("qty_potion", call_if_exists(inv, "get_quantity", ["potion"], 0) == 3, "get_quantity('potion') deve restituire 3")
	check("occupied_1", call_if_exists(inv, "get_occupied_slots", [], 0) == 1, "get_occupied_slots() deve restituire 1")
	check("total_1", call_if_exists(inv, "get_total_items_count", [], 0) == 3, "get_total_items_count() deve restituire 3")

	var stack_potion = call_if_exists(inv, "add_item", ["potion", 2], false)
	check("stack_potion", stack_potion == true, "Aggiungere altre pozioni deve riuscire accumulandosi sullo stesso slot")
	check("qty_potion_stack", call_if_exists(inv, "get_quantity", ["potion"], 0) == 5, "La quantita di pozioni dopo accumulo deve essere 5")
	check("occupied_still_1", call_if_exists(inv, "get_occupied_slots", [], 0) == 1, "Gli slot occupati devono rimanere 1 dopo l'accumulo")

	var add_key = call_if_exists(inv, "add_item", ["key", 1], false)
	check("add_key", add_key == true, "Aggiungere un secondo tipo di oggetto deve occupare il secondo slot")
	check("occupied_2", call_if_exists(inv, "get_occupied_slots", [], 0) == 2, "Gli slot occupati devono essere 2")

	var add_sword = call_if_exists(inv, "add_item", ["sword", 1], false)
	check("add_sword_fail", add_sword == false, "Aggiungere un terzo oggetto con limite a 2 slot deve restituire false")

	var add_zero = call_if_exists(inv, "add_item", ["potion", 0], true)
	check("add_zero", add_zero == false, "add_item con quantita <= 0 deve restituire false")

	var rem_part = call_if_exists(inv, "remove_item", ["potion", 2], false)
	check("rem_part", rem_part == true, "remove_item('potion', 2) su 5 disponibili deve restituire true")
	check("qty_after_rem", call_if_exists(inv, "get_quantity", ["potion"], 0) == 3, "Dopo la rimozione devono rimanere 3 pozioni")

	var rem_too_much = call_if_exists(inv, "remove_item", ["potion", 10], true)
	check("rem_too_much", rem_too_much == false, "Rimuovere piu oggetti di quelli posseduti deve restituire false")

	var rem_all_keys = call_if_exists(inv, "remove_item", ["key", 1], false)
	check("rem_all_keys", rem_all_keys == true, "Rimuovere l'unica chiave deve restituire true ed eliminare lo slot")
	check("key_qty_zero", call_if_exists(inv, "get_quantity", ["key"], -1) == 0, "La quantita della chiave azzerata deve essere 0")
	check("occupied_back_to_1", call_if_exists(inv, "get_occupied_slots", [], 0) == 1, "Dopo aver azzerato la chiave gli slot occupati devono tornare a 1")

	var add_sword_retry = call_if_exists(inv, "add_item", ["sword", 1], false)
	check("add_sword_retry", add_sword_retry == true, "Dopo aver liberato uno slot, l'aggiunta della spada deve riuscire")

	var map_script: GDScript = load("res://room_map.gd") as GDScript
	if not check("map_script", map_script != null, "Lo script res://room_map.gd deve esistere e compilare senza errori"):
		return
	var map = map_script.new()
	call_if_exists(map, "add_room", ["entry", "Atrio d'ingresso"])
	check("default_room", str(get_prop(map, "current_room", "")) == "entry", "La prima stanza aggiunta deve diventare current_room ('entry')")

	call_if_exists(map, "add_room", ["hall", "Salone principale"])
	check("desc_entry", str(call_if_exists(map, "get_room_description", ["entry"], "")) == "Atrio d'ingresso", "get_room_description deve restituire la descrizione corretta")

	var conn_ok = call_if_exists(map, "connect_rooms", ["entry", "north", "hall"], false)
	check("conn_ok", conn_ok == true, "connect_rooms tra due stanze esistenti deve restituire true")
	var conn_invalid = call_if_exists(map, "connect_rooms", ["entry", "south", "nonexistent"], true)
	check("conn_invalid", conn_invalid == false, "connect_rooms con stanza inesistente deve restituire false")

	var exits = call_if_exists(map, "get_available_directions", [], [])
	check("exits_has_north", exits is Array and exits.has("north"), "get_available_directions da 'entry' deve includere 'north'")
	check("dest_north", str(call_if_exists(map, "get_destination", ["north"], "")) == "hall", "get_destination('north') deve essere 'hall'")

	var move_ok = call_if_exists(map, "move", ["north"], false)
	check("move_ok", move_ok == true, "move verso un'uscita valida deve restituire true")
	check("new_room", str(get_prop(map, "current_room", "")) == "hall", "Dopo move('north'), current_room deve essere 'hall'")

	var move_fail = call_if_exists(map, "move", ["east"], true)
	check("move_fail", move_fail == false, "move verso una direzione senza uscita deve restituire false")
	check("room_unchanged", str(get_prop(map, "current_room", "")) == "hall", "Un movimento fallito non deve cambiare current_room")

