class_name Inventory
extends RefCounted

var max_slots: int = 10
var _items: Dictionary = {}


func _init(p_max_slots: int = 10) -> void:
	max_slots = p_max_slots


func add_item(item_id: String, amount: int = 1) -> bool:
	if amount <= 0:
		return false
	var current_amount: int = int(_items.get(item_id, 0))
	if current_amount == 0 and _items.size() >= max_slots:
		return false
	_items[item_id] = current_amount + amount
	return true


func remove_item(item_id: String, amount: int = 1) -> bool:
	if amount <= 0 or not _items.has(item_id):
		return false
	var current_amount: int = int(_items[item_id])
	if current_amount < amount:
		return false
	current_amount -= amount
	if current_amount == 0:
		_items.erase(item_id)
	else:
		_items[item_id] = current_amount
	return true


func get_quantity(item_id: String) -> int:
	return int(_items.get(item_id, 0))


func has_item(item_id: String, amount: int = 1) -> bool:
	return get_quantity(item_id) >= amount


func get_occupied_slots() -> int:
	return _items.size()


func get_total_items_count() -> int:
	var total: int = 0
	for item_id in _items:
		total += int(_items[item_id])
	return total

class_name RoomMap
extends RefCounted

var current_room: String = ""
var _rooms: Dictionary = {}


func add_room(room_id: String, description: String) -> void:
	_rooms[room_id] = {
		"description": description,
		"exits": {}
	}
	if current_room == "":
		current_room = room_id


func connect_rooms(from_id: String, direction: String, to_id: String) -> bool:
	if not _rooms.has(from_id) or not _rooms.has(to_id):
		return false
	var exits: Dictionary = _rooms[from_id]["exits"]
	exits[direction] = to_id
	return true


func get_room_description(room_id: String) -> String:
	if not _rooms.has(room_id):
		return ""
	return str(_rooms[room_id]["description"])


func get_available_directions() -> Array[String]:
	if current_room == "" or not _rooms.has(current_room):
		return []
	var exits: Dictionary = _rooms[current_room]["exits"]
	var result: Array[String] = []
	for dir in exits:
		result.append(str(dir))
	return result


func get_destination(direction: String) -> String:
	if current_room == "" or not _rooms.has(current_room):
		return ""
	var exits: Dictionary = _rooms[current_room]["exits"]
	return str(exits.get(direction, ""))


func move(direction: String) -> bool:
	var dest: String = get_destination(direction)
	if dest == "":
		return false
	current_room = dest
	return true

class_name ItemCatalog
extends RefCounted

var items: Array = []


func add_item(id: String, name: String, price: int) -> void:
	for item in items:
		if item["id"] == id:
			item["name"] = name
			item["price"] = price
			return
	items.append({"id": id, "name": name, "price": price})


func has_item(id: String) -> bool:
	for item in items:
		if item["id"] == id:
			return true
	return false


func get_price(id: String) -> int:
	for item in items:
		if item["id"] == id:
			return item["price"]
	return 0


func get_name(id: String) -> String:
	for item in items:
		if item["id"] == id:
			return item["name"]
	return ""


func remove_item(id: String) -> bool:
	for i in range(items.size()):
		if items[i]["id"] == id:
			items.remove_at(i)
			return true
	return false


func get_item_count() -> int:
	return items.size()

class_name ItemCatalog
extends RefCounted

var _items: Dictionary = {}


func add_item(id: String, name: String, price: int) -> void:
	_items[id] = {"name": name, "price": price}


func has_item(id: String) -> bool:
	return _items.has(id)


func get_price(id: String) -> int:
	if not _items.has(id):
		return 0
	return int(_items[id]["price"])


func get_name(id: String) -> String:
	if not _items.has(id):
		return ""
	return str(_items[id]["name"])


func remove_item(id: String) -> bool:
	if not _items.has(id):
		return false
	_items.erase(id)
	return true


func get_item_count() -> int:
	return _items.size()

class_name DungeonNavigator
extends RefCounted

var current_room: String = "entrance"


func get_room_name() -> String:
	if current_room == "entrance":
		return "Ingresso della Fortezza"
	elif current_room == "hall":
		return "Grande Atrio"
	elif current_room == "armory":
		return "Armeria Reale"
	elif current_room == "library":
		return "Antica Biblioteca"
	elif current_room == "treasury":
		return "Sala del Tesoro"
	return "Stanza Sconosciuta"


func get_destination(direction: String) -> String:
	if current_room == "entrance":
		if direction == "north":
			return "hall"
	elif current_room == "hall":
		if direction == "south":
			return "entrance"
		elif direction == "east":
			return "armory"
		elif direction == "west":
			return "library"
		elif direction == "north":
			return "treasury"
	elif current_room == "armory":
		if direction == "west":
			return "hall"
	elif current_room == "library":
		if direction == "east":
			return "hall"
	elif current_room == "treasury":
		if direction == "south":
			return "hall"
	return ""


func can_move(direction: String) -> bool:
	if current_room == "entrance":
		if direction == "north":
			return true
	elif current_room == "hall":
		if direction == "south" or direction == "east" or direction == "west" or direction == "north":
			return true
	elif current_room == "armory":
		if direction == "west":
			return true
	elif current_room == "library":
		if direction == "east":
			return true
	elif current_room == "treasury":
		if direction == "south":
			return true
	return false


func move(direction: String) -> bool:
	var dest: String = get_destination(direction)
	if dest != "":
		current_room = dest
		return true
	return false


func get_available_directions() -> Array[String]:
	if current_room == "entrance":
		return ["north"]
	elif current_room == "hall":
		return ["south", "east", "west", "north"]
	elif current_room == "armory":
		return ["west"]
	elif current_room == "library":
		return ["east"]
	elif current_room == "treasury":
		return ["south"]
	return []

class_name DungeonNavigator
extends RefCounted

var current_room: String = "entrance"

const ROOMS: Dictionary = {
	"entrance": {
		"name": "Ingresso della Fortezza",
		"exits": {"north": "hall"}
	},
	"hall": {
